  "hh.todayTips": "Ndụmọdụ Taa",
  "hh.using1": "Akụkọ H2H bụ ọnụọgụgụ a na-atụkwasịkarị obi n'ụzọ na-ezughị oke n'ịnọ nzọ egwuregwu bọọlụ. Ndị egwuregwu na-agbanwe, ndị nchịkọta na-agbanwe, otu 4–0 nke mere afọ atọ gara aga na-agwa gị banyere otu na-adịkwaghị adị. Ebe ndekọ ndị a nwere ezi ozi bụ na mkpokọta: ọdịiche atụmatụ na-eme mgbe mgbe, ọdụ ndị otu na-anọ na-adaru mba, na njikọ otu ndị egwuregwu ha na-adịkarị elu ma ọ bụ ala na gọọlụ.",
  "hh.using2": "Nke ikpeazụ bụ ihe bara uru n'ezie. Njikọ otu nwere nkezi karịrị ma ọ bụ dị ala karịa ọkọlọtọ asọmpi bụ gọọlụ {avg} n'ime ọtụtụ egwuregwu kwesịrị ka a lelee ya megide ahịrị ngụkọta gọọlụ ugbu a — ọ bụghị dị ka akara n'onwe ya, kama dị ka ihe na-akpali oge ilekwuo anya. Ihe atụ anyị anaghị eji ndekọ H2H eme ihe ma ọlị, kama ọ na-arụ ọrụ site n'ọnụọgụgụ gọọlụ ndị otu ọ bụla na-emenye na nke ha na-anabata ugbu a, nke bụ ntọala kwụsiri ike karịa; werenụ peeji ndị a dị ka ihe ndabere, ọ bụghị dị ka usoro.",
  "hh.usingH": "Iji ndekọ ihu na ihu {league} nke ọma",
  "hh.wdlNote": "W/D/L egosipụtara site n'anya {team}. Nsonaazụ si n'oge egwuregwu dị na data anyị — ọ bụghị ndekọ akụkọ ihe mere eme zuru oke nke ndị otu.",
  "hh.whatFor1": "Saịtị nzọ ihe ọ bụla na-ebipụta ndekọ H2H, ọtụtụ ndị na-agụ ha na-atụkwasị ha obi karịrị ekwesị. Nzukọ nke mere afọ anọ gara aga metụtara ndị egwuregwu dị iche, ndị nchịkọta dị iche na-abụkarịkwa ọkwa dị iche — ọ na-agwakarịghị ihe ọ bụla banyere nkeji iri itoolu na iri ise ọzọ na-abịa. Ihe eji ihe atụ anyị agbanwe zuru ha ọzọ na-elebara ndekọ H2H, kama ọ na-arụ ọrụ site na ọnụọgụgụ gọọlụ ndị otu ọ bụla na-emenye na nke ha na-anabata ugbu a.",
  "hh.whatFor2": "Ihe fọdụrụ mgbe a nyochachara nke ọma bụ mkpokọta. Njikọ otu ndị na-akwụsị na-emepụta gọọlụ — ma ọ bụ na-akwụsị egbochi ibe ha gọọlụ — na-egosikarị ọdịiche n'atụmatụ egwuregwu karịa ihe mberede, nke kwesịrị ka a lelee ya megide ahịrị ngụkọta gọọlụ ugbu a. Gụọ peeji ndị a maka nke ahụ na maka akụkọ ihe mere eme; wepụta ohere gaa n'ọnụahịa na ihe atụ.",
